class Solution {
public:
    long long makeIntegerBeautiful(long long n, int target) {
        auto ds = [](long long v){ int s = 0; while (v) { s += v % 10; v /= 10; } return s; };
        long long x = 0;
        while (ds(n + x) > target) x++;
        return x;
    }
};

