var makeIntegerBeautiful = function(n, target) {
    const ds = v => { let s = 0; while (v > 0) { s += v % 10; v = Math.floor(v / 10); } return s; };
    let base = 0, p = 1;
    while (ds(n + base) > target) {
        base = (Math.floor(base / p) + 1) * p;
        p *= 10;
